package proj

import (
	"bufio"
	"bytes"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

// 手写占比(boundaries.md §8.2): 一个项目的服务代码里,多少行是工厂生成的,多少行是人(或 AI)写的。
//
// 量什么(服务代码 = 镜像里编译的东西,和 Dockerfile 复制的范围一样):
//   - cmd/、internal/、gen/ 下的 *.go,不含 *_test.go(测试不进镜像,另算)
//   - db/queries/*.sql(sqlc 的输入)
//   - 不量: design/(设计书是输入,不是代码)、specs/ proto/(从设计书生成的中间产物)、db/schema/(建表由设计者写,
//     是设计的一部分)、测试、Dockerfile 等配置
//
// 怎么分:
//   - 生成: 文件开头(第一个非注释行之前)有 Go 的标准标记 "Code generated … DO NOT EDIT."(// -- # 注释都认)
//   - 手写: 其余的文件 —— compute 的逻辑(*_logic.go)、custom 的处理器、cmd/server/main.go 这类项目自己的文件
//   - 例外: db/queries 里从 datasource.sql(逃生口)抄过来的查询,虽然带生成标记,内容是人写的 → 手写
//     (标记里的 "from specs/…/spec.yaml" 指向的式样书写了 datasource.sql)
//   - 行 = 非空行(注释算)
//   - 生成的行里另外记下工具链(标记里有 "by protoc-gen-…" / "by sqlc")的部分: 它们由工厂驱动,
//     但量很大(.pb.go),所以也报告只算工厂自己输出的口径

// LineStats: 按类别的非空行数。
type LineStats struct {
	Generated int
	Tools     int            // Generated 里由工具链(protoc-gen-go、protoc-gen-connect-go、sqlc)生成的行
	Hand      map[string]int // 类别 → 行: "cmd/" "internal/" "gen/" 下的手写 Go;"escape-sql" 逃生口的查询
	HandFiles []string       // 手写的文件(排好序;报告 / 测试用)
}

// HandTotal: 手写的总行数。
func (s LineStats) HandTotal() int {
	n := 0
	for _, v := range s.Hand {
		n += v
	}
	return n
}

// HandRatio: 手写 / (手写 + 生成),没有代码时 0。
func (s LineStats) HandRatio() float64 { return ratio(s.HandTotal(), s.Generated) }

// HandRatioFactoryOnly: 生成的只算工厂自己写出的(不算 protoc / sqlc 的输出)—— 更保守的口径。
func (s LineStats) HandRatioFactoryOnly() float64 { return ratio(s.HandTotal(), s.Generated-s.Tools) }

func ratio(hand, generated int) float64 {
	if hand+generated == 0 {
		return 0
	}
	return float64(hand) / float64(hand+generated)
}

var (
	generatedMarker = regexp.MustCompile(`^(//|--|#)\s*Code generated .* DO NOT EDIT\.?\s*$`)
	generatedFrom   = regexp.MustCompile(`Code generated by factory from (\S+?)\.? DO NOT EDIT`)
	toolMarker      = regexp.MustCompile(`Code generated by (protoc-gen-\S+|sqlc)`)
)

// CountLines: root(项目根目录)的服务代码按生成 / 手写分开数。escapeSpecs: 写了 datasource.sql 的式样书的路径
// (相对 root,如 specs/sales/x/spec.yaml)—— 从它们生成的查询算手写。
func CountLines(root string, escapeSpecs map[string]bool) (LineStats, error) {
	st := LineStats{Hand: map[string]int{}}
	add := func(rel string, generated, tool bool, category string, n int) {
		if generated {
			st.Generated += n
			if tool {
				st.Tools += n
			}
			return
		}
		st.Hand[category] += n
		st.HandFiles = append(st.HandFiles, rel)
	}
	for _, dir := range []string{"cmd", "internal", "gen"} {
		err := filepath.WalkDir(filepath.Join(root, dir), func(p string, d fs.DirEntry, err error) error {
			if err != nil {
				if os.IsNotExist(err) {
					return filepath.SkipDir
				}
				return err
			}
			if d.IsDir() || !strings.HasSuffix(p, ".go") || strings.HasSuffix(p, "_test.go") {
				return nil
			}
			b, err := os.ReadFile(p)
			if err != nil {
				return err
			}
			rel, _ := filepath.Rel(root, p)
			gen, tool, _ := header(b)
			add(filepath.ToSlash(rel), gen, tool, dir+"/", nonBlank(b))
			return nil
		})
		if err != nil {
			return st, err
		}
	}
	queries, err := filepath.Glob(filepath.Join(root, "db", "queries", "*.sql"))
	if err != nil {
		return st, err
	}
	for _, q := range queries {
		b, err := os.ReadFile(q)
		if err != nil {
			return st, err
		}
		gen, tool, from := header(b)
		if escapeSpecs[from] {
			gen = false
		}
		rel, _ := filepath.Rel(root, q)
		add(filepath.ToSlash(rel), gen, tool, "escape-sql", nonBlank(b))
	}
	sort.Strings(st.HandFiles)
	return st, nil
}

// header: 文件开头的注释块(第一个代码行之前)里的生成标记。generated = 有标记;tool = 有一个标记是工具链的
// ("by protoc-gen-…" / "by sqlc": 工厂给 protoc 的输出再加一行自己的标记,所以要看全部标记);from = "from <path>"。
func header(b []byte) (generated, tool bool, from string) {
	sc := bufio.NewScanner(bytes.NewReader(b))
	sc.Buffer(make([]byte, 0, 64*1024), 1<<20)
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		if line == "" {
			continue
		}
		if !strings.HasPrefix(line, "//") && !strings.HasPrefix(line, "--") && !strings.HasPrefix(line, "#") {
			break // 第一个代码行
		}
		if !generatedMarker.MatchString(line) {
			continue
		}
		generated = true
		if toolMarker.MatchString(line) {
			tool = true
		}
		if m := generatedFrom.FindStringSubmatch(line); m != nil && from == "" {
			from = m[1]
		}
	}
	return generated, tool, from
}

func nonBlank(b []byte) int {
	n := 0
	for _, l := range bytes.Split(b, []byte("\n")) {
		if len(bytes.TrimSpace(l)) > 0 {
			n++
		}
	}
	return n
}

// Header 读文件开头的生成标记: generated = 有 "Code generated ... DO NOT EDIT";tool = protoc / sqlc 生成;
// from = "Code generated by factory from <from>" 的来源(式样书或设计书的路径)。
func Header(b []byte) (generated, tool bool, from string) { return header(b) }
